/* samples.js - the built-in sources behind the Source panel's own control.
 *
 * Three paintings travel inside the app, so a fresh window has something with
 * some weight in it before anything is loaded: the Source panel's control (and
 * the Ctrl+D accelerator, and File > the demo scene) steps through these, then
 * the generated scene, and comes round again on the first.
 *
 * They are inlined as data URIs rather than shipped as image files because the
 * console also runs from `file://` (the launchers, and any browser opening
 * `index.html` straight off disk), and there a local file may not be read back
 * out of the canvas: drawing it taints the canvas and getImageData() throws a
 * SecurityError. A data URI never taints, so one table serves every build, at
 * every origin, with no fetch, no server and no build step.
 *
 * The paintings are public domain. Each was encoded once at WebP quality 80,
 * which is the smallest form that still keeps the brushwork legible under a
 * dither screen; SOURCES.md records the work, the artist and the recipe, and
 * DEVELOPMENT.md says how to regenerate the table.
 *
 * Exposes: window.DitherSamples - [{ name, data }], in the order they are
 * stepped through. An absent or empty table leaves the generated scene as the
 * only source, which is how the shells behave if this file is ever left out.
 */
window.DitherSamples = [
  // Gustave Moreau, Oedipus and the Sphinx, 1864, detail - The Met, New York (21.134.1), public domain / CC0
  {
    name: 'Oedipus and the Sphinx',
    data: 'data:image/webp;base64,',
  },
  // Mårten Eskil Winge, Tors strid med jättarna, 1872 - Nationalmuseum, Stockholm (NM 1250), public domain
  {
    name: 'Tor\'s Fight with the Giants',
    data: 'data:image/webp;base64,',
  },
  // The Council of the Gods, Raphael and his workshop, 1517-18 - Villa Farnesina, Rome, public domain
  {
    name: 'The Council of the Gods',
    data: 'data:image/webp;base64,',
  }
];
